class Root { int r_val; };

// Derived classes contain a hidden Virtual Base Pointer (vbptr)
class Left : virtual public Root {
    // Hidden: vbptr added here to locate Root
    int l_val;
};

class Right : virtual public Root {
    // Hidden: vbptr added here to locate Root
    int r_val;
};

// Diamond problem solved: Only one Root subobject
class Join : public Left, public Right { int j_val; };

// Access (Join*) -> vbptr -> VBC Table -> Offset -> Root
// Root is usually appended after the last non-virtual base subobject.
